-- Schema v1. Autoritativ: Store.migrate().
PRAGMA foreign_keys=ON;
CREATE TABLE accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,balance INTEGER NOT NULL CHECK(balance>=0 AND balance<=9000000000000000),menu INTEGER NOT NULL DEFAULT 0,income INTEGER NOT NULL DEFAULT 0);
CREATE TABLE ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,operation TEXT NOT NULL,account TEXT NOT NULL,delta INTEGER NOT NULL,reason TEXT NOT NULL,at INTEGER NOT NULL);
CREATE TABLE operations(id TEXT PRIMARY KEY,kind TEXT NOT NULL,owner TEXT NOT NULL,state TEXT NOT NULL,payload TEXT NOT NULL,at INTEGER NOT NULL,resolution TEXT);
CREATE TABLE stock(material TEXT PRIMARY KEY,quantity INTEGER NOT NULL CHECK(quantity>=0),bonus_carry TEXT NOT NULL DEFAULT '0/1');
CREATE TABLE suppliers(material TEXT NOT NULL,owner TEXT NOT NULL,units TEXT NOT NULL,carry TEXT NOT NULL,PRIMARY KEY(material,owner));
CREATE TABLE shops(id TEXT PRIMARY KEY,owner TEXT NOT NULL,world TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,title TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,layout TEXT NOT NULL,UNIQUE(world,x,y,z));
CREATE TABLE offers(id TEXT PRIMARY KEY,shop TEXT NOT NULL REFERENCES shops(id) ON DELETE CASCADE,item TEXT NOT NULL,material TEXT NOT NULL,quantity INTEGER NOT NULL,price INTEGER NOT NULL CHECK(price>0),visible INTEGER NOT NULL);
CREATE TABLE auctions(id TEXT PRIMARY KEY,owner TEXT NOT NULL,item TEXT NOT NULL,material TEXT NOT NULL,price INTEGER NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL);
CREATE TABLE mailbox(id TEXT PRIMARY KEY,owner TEXT NOT NULL,item TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'READY',source TEXT NOT NULL UNIQUE);
CREATE TABLE votes(material TEXT NOT NULL,owner TEXT NOT NULL,round INTEGER NOT NULL,direction INTEGER NOT NULL,PRIMARY KEY(material,owner,round));
CREATE TABLE vote_results(material TEXT PRIMARY KEY,factor INTEGER NOT NULL DEFAULT 10000,round INTEGER NOT NULL DEFAULT -1,summary TEXT NOT NULL DEFAULT '');
CREATE TABLE credentials(hash TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX mailbox_owner ON mailbox(owner,state);
CREATE INDEX operation_state ON operations(state);
PRAGMA user_version=1;
